  1→import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
  2→import { createClient } from "https://esm.sh/@supabase/supabase-js@2.49.2";
  3→import { logSystemError, errorToMessage, errorToStack } from "../_shared/logError.ts";
  4→
  5→const corsHeaders = {
  6→  "Access-Control-Allow-Origin": "*",
  7→  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  8→};
  9→
 10→interface SendEmailRequest {
 11→  to: string;
 12→  template_key: string;
 13→  variables: Record<string, string>;
 14→}
 15→
 16→/** Replace {{variable}} placeholders in a template string */
 17→function renderTemplate(template: string, variables: Record<string, string>): string {
 18→  return template.replace(/\{\{(\w+)\}\}/g, (_, key) => variables[key] ?? "");
 19→}
 20→
 21→/** Map Postmark error codes to user-friendly messages */
 22→function getPostmarkErrorMessage(errorCode: number, message: string, fromEmail: string, toEmail: string): string {
 23→  switch (errorCode) {
 24→    case 412:
 25→      return `Account pending approval — emails can only be sent to @${fromEmail.split("@")[1]} addresses while your Postmark account is being reviewed. You tried sending to ${toEmail}.`;
 26→    case 406:
 27→      return `Inactive recipient — ${toEmail} has been marked as inactive due to previous bounces. Reactivate in Postmark dashboard.`;
 28→    case 300:
 29→      return `Sender signature not found — ${fromEmail} is not verified in Postmark. Add and verify this sender in your Postmark account.`;
 30→    case 400:
 31→      return `Bad request — ${message}`;
 32→    case 401:
 33→      return `Unauthorized — your Postmark API token is invalid or expired. Update it in Email Settings.`;
 34→    case 405:
 35→      return `Not allowed to send — ${message}`;
 36→    case 422:
 37→      return message || "Unprocessable request";
 38→    default:
 39→      return message || `Postmark error (code ${errorCode})`;
 40→  }
 41→}
 42→
 43→/** Send an email via Postmark API */
 44→async function sendViaPostmark(
 45→  apiToken: string,
 46→  from: { email: string; name: string },
 47→  to: string,
 48→  subject: string,
 49→  htmlContent: string
 50→): Promise<{ ok: boolean; status: number; body: string; errorCode?: number; errorMessage?: string }> {
 51→  const res = await fetch("https://api.postmarkapp.com/email", {
 52→    method: "POST",
 53→    headers: {
 54→      "Accept": "application/json",
 55→      "Content-Type": "application/json",
 56→      "X-Postmark-Server-Token": apiToken,
 57→    },
 58→    body: JSON.stringify({
 59→      From: `${from.name} <${from.email}>`,
 60→      To: to,
 61→      Subject: subject,
 62→      HtmlBody: htmlContent,
 63→      MessageStream: "outbound",
 64→    }),
 65→  });
 66→
 67→  const body = await res.text();
 68→  let errorCode: number | undefined;
 69→  let errorMessage: string | undefined;
 70→
 71→  if (!res.ok) {
 72→    try {
 73→      const parsed = JSON.parse(body);
 74→      errorCode = parsed.ErrorCode;
 75→      errorMessage = parsed.Message;
 76→    } catch { /* ignore */ }
 77→  }
 78→
 79→  return { ok: res.ok, status: res.status, body, errorCode, errorMessage };
 80→}
