 82→serve(async (req) => {
 83→  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
 84→
 85→  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
 86→  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
 87→  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
 88→
 89→  try {
 90→    const { to, template_key, variables } = (await req.json()) as SendEmailRequest;
 91→
 92→    if (!to || !template_key) {
 93→      return new Response(JSON.stringify({ error: "Missing 'to' or 'template_key'" }), {
 94→        status: 400,
 95→        headers: { ...corsHeaders, "Content-Type": "application/json" },
 96→      });
 97→    }
 98→
 99→    // Load platform config for Postmark credentials
100→    const { data: config, error: configError } = await supabase
101→      .from("platform_config")
102→      .select("postmark_api_token, email_from_address, email_from_name, outbound_email_enabled, email_notify_ranking_complete, email_notify_resume_received")
103→      .limit(1)
104→      .single();
105→
106→    if (configError) throw new Error(`Config error: ${configError.message}`);
107→
108→    if (!config?.outbound_email_enabled) {
109→      return new Response(JSON.stringify({ error: "Outbound email is disabled", skipped: true }), {
110→        status: 200,
111→        headers: { ...corsHeaders, "Content-Type": "application/json" },
112→      });
113→    }
114→
115→    if (!config.postmark_api_token) {
116→      return new Response(JSON.stringify({ error: "Postmark API token not configured" }), {
117→        status: 400,
118→        headers: { ...corsHeaders, "Content-Type": "application/json" },
119→      });
120→    }
121→
122→    // Check per-template notification settings
123→    if (template_key === "ranking_complete" && !config.email_notify_ranking_complete) {
124→      return new Response(JSON.stringify({ skipped: true, reason: "Ranking complete notifications disabled" }), {
125→        status: 200,
126→        headers: { ...corsHeaders, "Content-Type": "application/json" },
127→      });
128→    }
129→    if (template_key === "resume_received" && !config.email_notify_resume_received) {
130→      return new Response(JSON.stringify({ skipped: true, reason: "Resume received notifications disabled" }), {
131→        status: 200,
132→        headers: { ...corsHeaders, "Content-Type": "application/json" },
133→      });
134→    }
135→
136→    // Load template
137→    const { data: template, error: tplError } = await supabase
138→      .from("email_templates")
139→      .select("subject, body_html")
140→      .eq("template_key", template_key)
141→      .single();
142→
143→    if (tplError || !template) {
144→      return new Response(JSON.stringify({ error: `Template '${template_key}' not found` }), {
145→        status: 404,
146→        headers: { ...corsHeaders, "Content-Type": "application/json" },
147→      });
148→    }
149→
150→    // Render template with variables
151→    const subject = renderTemplate(template.subject, variables);
152→    const htmlContent = renderTemplate(template.body_html, variables);
153→
154→    const fromEmail = config.email_from_address || "noreply@rankora.co";
155→    const fromName = config.email_from_name || "Rankora";
156→
157→    // Send via Postmark
158→    const result = await sendViaPostmark(
159→      config.postmark_api_token,
160→      { email: fromEmail, name: fromName },
161→      to,
162→      subject,
163→      htmlContent
164→    );
165→
166→    if (!result.ok) {
167→      // If Postmark account is pending approval (error 412), silently skip external domain emails
168→      if (result.errorCode === 412) {
169→        const fromDomain = fromEmail.split("@")[1];
170→        const toDomain = to.split("@")[1];
171→        if (fromDomain !== toDomain) {
172→          console.warn(`Postmark pending approval: skipping email to ${toDomain} (only ${fromDomain} allowed)`);
173→          return new Response(JSON.stringify({
174→            skipped: true,
175→            reason: `Postmark account pending approval — can only send to @${fromDomain} addresses`,
176→          }), {
177→            status: 200,
178→            headers: { ...corsHeaders, "Content-Type": "application/json" },
179→          });
180→        }
181→      }
182→
183→      const friendlyMessage = getPostmarkErrorMessage(
184→        result.errorCode || 0,
185→        result.errorMessage || "",
186→        fromEmail,
187→        to
188→      );
189→
190→      console.error("Postmark error:", result.status, result.body);
191→      await logSystemError({
192→        function_name: "send-email",
193→        error_type: "POSTMARK_SEND_ERROR",
194→        severity: "warning",
195→        error_message: `Postmark error: status=${result.status} body=${result.body}`,
196→      });
197→      return new Response(JSON.stringify({
198→        error: friendlyMessage,
199→        postmark_error_code: result.errorCode,
200→        postmark_raw: result.errorMessage,
201→      }), {
202→        status: 502,
203→        headers: { ...corsHeaders, "Content-Type": "application/json" },
204→      });
205→    }
206→
207→    return new Response(JSON.stringify({ success: true }), {
208→      status: 200,
209→      headers: { ...corsHeaders, "Content-Type": "application/json" },
210→    });
211→  } catch (err: unknown) {
212→    console.error("send-email error:", err);
213→    await logSystemError({
214→      function_name: "send-email",
215→      error_type: "EMAIL_SEND_ERROR",
216→      severity: "warning",
217→      error_message: errorToMessage(err),
218→      error_stack: errorToStack(err),
219→    });
220→    return new Response(JSON.stringify({ error: err instanceof Error ? err.message : String(err) }), {
221→      status: 500,
222→      headers: { ...corsHeaders, "Content-Type": "application/json" },
223→    });
224→  }
225→});
