 18→/** Send an email via Postmark API */
 19→async function sendViaPostmark(
 20→  apiToken: string,
 21→  from: { email: string; name: string },
 22→  to: string,
 23→  subject: string,
 24→  htmlContent: string
 25→): Promise<{ ok: boolean; status: number; body: string; errorCode?: number; errorMessage?: string }> {
 26→  const res = await fetch("https://api.postmarkapp.com/email", {
 27→    method: "POST",
 28→    headers: {
 29→      "Accept": "application/json",
 30→      "Content-Type": "application/json",
 31→      "X-Postmark-Server-Token": apiToken,
 32→    },
 33→    body: JSON.stringify({
 34→      From: `${from.name} <${from.email}>`,
 35→      To: to,
 36→      Subject: subject,
 37→      HtmlBody: htmlContent,
 38→      MessageStream: "outbound",
 39→    }),
 40→  });
 41→
 42→  const body = await res.text();
 43→  let errorCode: number | undefined;
 44→  let errorMessage: string | undefined;
 45→
 46→  if (!res.ok) {
 47→    try {
 48→      const parsed = JSON.parse(body);
 49→      errorCode = parsed.ErrorCode;
 50→      errorMessage = parsed.Message;
 51→    } catch { /* ignore */ }
 52→  }
 53→
 54→  return { ok: res.ok, status: res.status, body, errorCode, errorMessage };
 55→}
 56→
 57→serve(async (req) => {
 58→  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
 59→
 60→  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
 61→  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
 62→  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
 63→
 64→  // Verify JWT
 65→  const authHeader = req.headers.get("Authorization");
 66→  if (!authHeader) {
 67→    return new Response(JSON.stringify({ error: "Missing authorization header" }), {
 68→      status: 401,
 69→      headers: { ...corsHeaders, "Content-Type": "application/json" },
 70→    });
 71→  }
 72→
 73→  const token = authHeader.replace("Bearer ", "");
 74→  const { data: { user }, error: authError } = await supabase.auth.getUser(token);
 75→  if (authError || !user) {
 76→    return new Response(JSON.stringify({ error: "Unauthorized" }), {
 77→      status: 401,
 78→      headers: { ...corsHeaders, "Content-Type": "application/json" },
 79→    });
 80→  }
 81→
 82→  try {
 83→    const { resume_id, job_id, to_email, subject, body_html } =
 84→      (await req.json()) as SendCandidateEmailRequest;
 85→
 86→    if (!resume_id || !job_id || !to_email || !subject || !body_html) {
 87→      return new Response(
 88→        JSON.stringify({ error: "Missing required fields: resume_id, job_id, to_email, subject, body_html" }),
 89→        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
 90→      );
 91→    }
 92→
 93→    // Load platform config for Postmark credentials
 94→    const { data: config, error: configError } = await supabase
 95→      .from("platform_config")
 96→      .select("postmark_api_token, email_from_address, email_from_name, outbound_email_enabled")
 97→      .limit(1)
 98→      .single();
 99→
100→    if (configError) throw new Error(`Config error: ${configError.message}`);
101→
102→    if (!config?.outbound_email_enabled) {
103→      return new Response(JSON.stringify({ error: "Outbound email is disabled", skipped: true }), {
104→        status: 200,
105→        headers: { ...corsHeaders, "Content-Type": "application/json" },
106→      });
107→    }
108→
109→    if (!config.postmark_api_token) {
110→      return new Response(JSON.stringify({ error: "Postmark API token not configured" }), {
111→        status: 400,
112→        headers: { ...corsHeaders, "Content-Type": "application/json" },
113→      });
114→    }
115→
116→    const fromEmail = config.email_from_address || "noreply@rankora.co";
117→    const fromName = config.email_from_name || "Rankora";
118→
119→    // Send via Postmark
120→    const result = await sendViaPostmark(
121→      config.postmark_api_token,
122→      { email: fromEmail, name: fromName },
123→      to_email,
124→      subject,
125→      body_html
126→    );
127→
128→    const logStatus = result.ok ? "sent" : "failed";
129→
130→    // Log to outreach_log regardless of send result
131→    const { error: logError } = await supabase.from("outreach_log").insert({
132→      resume_id,
133→      job_id,
134→      type: "email",
135→      to_address: to_email,
136→      subject,
137→      status: logStatus,
138→      user_id: user.id,
139→    });
140→
141→    if (logError) {
142→      console.error("Failed to log outreach:", logError.message);
143→      await logSystemError({
144→        function_name: "send-candidate-email",
145→        error_type: "OUTREACH_LOG_ERROR",
146→        severity: "warning",
147→        error_message: `Failed to log outreach: ${logError.message}`,
148→        user_id: user.id,
149→        job_id,
150→      });
151→    }
152→
153→    if (!result.ok) {
154→      let errorMessage = result.errorMessage || `Postmark error (status ${result.status})`;
155→      if (result.errorCode === 412) {
156→        errorMessage = `Account pending approval — emails can only be sent to verified addresses while your Postmark account is being reviewed.`;
157→      } else if (result.errorCode === 406) {
158→        errorMessage = `Inactive recipient — ${to_email} has been marked as inactive due to previous bounces.`;
159→      } else if (result.errorCode === 300) {
160→        errorMessage = `Sender signature not found — ${fromEmail} is not verified in Postmark.`;
161→      } else if (result.errorCode === 401) {
162→        errorMessage = `Unauthorized — your Postmark API token is invalid or expired.`;
163→      }
164→
165→      console.error("Postmark error:", result.status, result.body);
166→      await logSystemError({
167→        function_name: "send-candidate-email",
168→        error_type: "POSTMARK_SEND_ERROR",
169→        severity: "warning",
170→        error_message: `Postmark error: status=${result.status} body=${result.body}`,
171→        user_id: user.id,
172→        job_id,
173→      });
174→      return new Response(
175→        JSON.stringify({
176→          error: errorMessage,
177→          postmark_error_code: result.errorCode,
178→        }),
179→        { status: 502, headers: { ...corsHeaders, "Content-Type": "application/json" } }
180→      );
181→    }
182→
183→    return new Response(JSON.stringify({ success: true }), {
184→      status: 200,
185→      headers: { ...corsHeaders, "Content-Type": "application/json" },
186→    });
187→  } catch (err: unknown) {
188→    console.error("send-candidate-email error:", err);
189→    await logSystemError({
190→      function_name: "send-candidate-email",
191→      error_type: "EMAIL_SEND_ERROR",
192→      severity: "warning",
193→      error_message: errorToMessage(err),
194→      error_stack: errorToStack(err),
195→    });
196→    return new Response(
197→      JSON.stringify({ error: err instanceof Error ? err.message : String(err) }),
198→      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
199→    );
200→  }
201→});
